if ((flags & 0x8000) != 0) {
    int index = 0;
    if (edge_count > 0) {
        int edge_offset = 0;
        int saved_edge_offset = 0;
        do {
            ObjectToonEdge* edge = (ObjectToonEdge*)((char*)build_edges + edge_offset);
            if ((edge->flags & OBJECT_TOON_EDGE_FLAG_BOUNDARY) != 0) {
                int shift_index = index;
                if (index < edge_count - 1) {
                    do {
                        memcpy((char*)build_edges + edge_offset,
                            (char*)build_edges + edge_offset + sizeof(ObjectToonEdge),
                            sizeof(ObjectToonEdge));
                        ++shift_index;
                        edge_count = g_object_edge_build_count;
                        build_edges = g_object_edge_build_edges;
                        edge_offset += sizeof(ObjectToonEdge);
                    } while (shift_index < g_object_edge_build_count - 1);
                    edge_offset = saved_edge_offset;
                }
                --edge_count;
                g_object_edge_build_count = edge_count;
                --index;
                edge_offset -= sizeof(ObjectToonEdge);
            }
            ++index;
            edge_offset += sizeof(ObjectToonEdge);
            saved_edge_offset = edge_offset;
        } while (index < edge_count);
    }
}

